async function open(next){if(!api.user())return;route={...next};if(route.view==='home'&&members.length===1)route={view:'team',team:members[0].team_id};if(route.team&&!has(route.team)){route={view:'home'};}if(route.view==='adminannouncements'&&!anyAdmin())route={view:'home'};if(route.view==='settings'&&!rootAdmin())route={view:'home'};if(route.view==='teamadmin'&&!isAdmin(route.team))route={view:'team',team:route.team};const area=route.view==='links'?'spreadsheets':['training','tools','projects','meetings'].includes(route.view)?route.view:null;if(area&&(!assigned(route.team,area)||!allowed(route.team,area)))route={view:'team',team:route.team};if(route.view==='home'&&members.length===1)route={view:'team',team:members[0].team_id};workDirty=false;GuhuzaUI.show('portal');const root=$('portalPanel'),ticket=++run;root.replaceChildren();root.classList.toggle('has-team-navigation',false);crumb(root);if(route.team&&['training','tools','projects','meetings','links','announcements','issues'].includes(route.view)){root.classList.add('has-team-navigation');const tabs=el('nav',undefined,'team-area-nav');tabs.setAttribute('aria-label','Team areas');for(const [view,label]of [['team','Team home'],['training','Training'],['projects','Tasks & projects'],['meetings','Meetings'],['interviews','Interviews'],['tools','Resources & tools'],['links','Spreadsheets'],['announcements','Announcements'],['issues','Report an issue'],['teamadmin','Team admin']]){const area=view==='links'?'spreadsheets':view;if(view!=='team'&&(!assigned(route.team,area)||view==='interviews'&&route.team!=='hr'))continue;const team=route.team;const b=button(label,()=>view==='interviews'?enterArea(team,'interviews'):open({view,team}));b.setAttribute('aria-pressed',String(route.view===view));if(['training','projects'].includes(view))b.append(activityBadge(route.team,view));tabs.append(b);}root.append(tabs);}const body=el('div');body.className='portal-page-body';root.append(body);const loading=notice(body,'Loading workspace…');loading.className+=' workspace-loading';try{if(!loaded)throw Error('Team access is still loading. Use Refresh to retry.');if(route.view==='home')home(body);else if(route.view==='team')teamHome(body);else if(['training','tools'].includes(route.view)&&window.GuhuzaLearning)await GuhuzaLearning.render({root:body,team:route.team,api,state:{...route},documents:r=>resources(r,'training'),unlocks:async(r,item)=>unlockForm(r,item,(await all('training_unlocks',q=>q.eq('resource_id',item.id))).map(u=>u.area))});else if(route.view==='training'||route.view==='links')await resources(body,route.view);else if(route.view==='projects')await projects(body);else if(route.view==='issues')await GuhuzaIssues.render({root:body,team:route.team,api,state:{...route}});else if(route.view==='adminannouncements')await GuhuzaCommunity.adminRender({root:body,team:route.team,api});else if(route.view==='announcements')await GuhuzaCommunity.render({root:body,team:route.team,api,state:{...route}});else if(route.view==='settings')await settings(body);else if(route.view==='meetings')await GuhuzaMeetings.render({root:body,team:route.team,day:route.meetingDay,api,manage:route.meetingManage});else if(route.view==='teamadmin')await teamAdminHub(body);else home(body);}catch(e){if(ticket===run){notice(body,e.message);body.append(button('Retry',()=>open(route)));}}loading.remove();if(ticket===run)window.GuhuzaNavigation?.save();}

function unlockForm(root,resource,requirements){const details=el('details',undefined,'portal-manager');details.append(el('summary','Training unlock settings'));const form=el('form',undefined,'portal-form'),choices=[];for(const area of ['projects','spreadsheets','meetings',...(resource.team_id==='hr'?['interviews']:[])]){const label=el('label','Require this document before '+areaLabels[area]),input=el('input');input.type='checkbox';input.checked=requirements.includes(area);label.prepend(input);form.append(label);choices.push({area,input});}const save=el('button','Save unlock requirements');save.type='submit';const status=notice(form,'');form.append(save);details.append(form);root.append(details);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{check(await api.db.rpc('set_training_unlocks',{resource:resource.id,required_areas:choices.filter(c=>c.input.checked).map(c=>c.area)}));status.textContent='Requirements saved. Assigned areas unlock only after all required documents are marked complete.';}catch(err){status.textContent=err.message;}finally{save.disabled=false;}};}
async function enterArea(team,area){if(area==='issues'){await open({view:'issues',team,issueCompose:true});return;}if(!assigned(team,area))return;if(!allowed(team,area)){await open({view:'training',team});return;}if(area==='interviews')GuhuzaUI.show('home');else await open({view:area==='spreadsheets'?'links':area,team});if(area!=='tools'&&area!=='announcements'&&!guides.some(g=>g.team_id===team&&g.area===area))showGuide(team,area);}
function showGuide(team,area,replay=false){guideDialog?.close();guideDialog?.remove();const dialog=el('dialog',undefined,'portal-guide');guideDialog=dialog;const img=el('img');img.src='gerrie-point.jpg';img.alt='Gerrie';const heading=el('h2'),text=el('p'),tip=el('p',undefined,'portal-note'),count=el('p',undefined,'eyebrow'),actions=el('div',undefined,'actions');const close=button('×',()=>dialog.close(),'portal-guide-close');close.setAttribute('aria-label','Close walkthrough');dialog.append(close,img,count,heading,text,tip,actions);document.body.append(dialog);const pages=area==='announcements'?[['Company news and your team board','Company announcements are shared with everyone. Your team board is for team announcements and everyday discussions. Lead and admin announcements are highlighted.','The company publishing controls are available only to admins.'],['Join the conversation','Open a post to comment or choose an emoji reaction. Publish helpful, relevant messages and keep private candidate information out of discussions.','Team posts are visible only to members of that team.'],['Stay in the loop','Use the bell for new announcements and team posts. Selecting a notification takes you directly to its conversation.','Gerrie’s meeting reminders appear in the portal shortly before a meeting starts.']]:area==='projects'?[['Tasks and projects','Projects are one-off assignments with due dates. Tasks can repeat daily, weekly, every two weeks, monthly or every three months on the weekdays and month weeks selected by the supervisor. A supervisor can assign either kind of work to several people.','Each person has their own status, submissions and completion history.'],['Your ongoing work','Use My work to see your assignments. Start work to record that you are in progress. Only the current scheduled occurrence appears here. Completion is separate for each due date. Use Calendar to browse future work.','Recurring work stops at your placement end, even if the task continues for other people.'],['Complete a recurring task','Describe what you completed in the required comment field, then complete today’s or this week’s task. Only mark work you have actually finished.','Completing today’s task does not complete tomorrow’s occurrence.'],['Submit a project','Use Upload completed work to choose your file and add notes. Submit completed work sends it for review; it does not approve the work automatically.','Use ZIP for several files. The per-file limit is 20 MB.'],['Reviews and revisions','Check your submission status and supervisor feedback. If changes are requested, upload a revised file. Another team admin must approve your own submission.','Earlier submissions and review events remain in your history.'],['Your work history','Switch View to Work history to see when assignments started, were submitted and were completed. Records use saved server timestamps in Toronto time.','Everyone can switch to Team overview for assignment names and descriptions. Completion comments and files from other people are admin-only. Use Calendar for upcoming dates.']]:area==='training'?[['Choose your training path','Your team library contains the workbook’s onboarding lessons. Admins can assign full training or a condensed set of lessons. Assigned to me shows your actual assignment and due dates.','Condensed means a selected set of lessons. It does not silently shorten every instruction.'],['Work through one section at a time','Use the section list on the left and open a lesson to read all steps, resource links and completion criteria. Search by topic when you need a specific lesson.','Some recordings show older spreadsheets. Record your learning progress here.'],['Complete the learning activity','Read or watch the linked material and practise only what the instructions allow. Use approved samples for exercises and ask your lead for missing access.','Training completion does not authorise live outreach, data changes or privileged accounts.'],['Record what you learned','Write a short learning or practice summary before marking a lesson complete. Where admin confirmation is required, it stays Awaiting admin review until a different team admin approves it.','Your learning notes are visible to you and team admins.'],['Find your team resources','Open Team resources for tools, trackers, templates and resource locations. Historical references, missing links and access conditions remain labelled.','A visible link does not grant access inside Google, Zoom, the CRM or another external system.'],['Understand resource access and unlocks','Some tools need individual portal access from an admin. Admins can also make selected lessons prerequisites for an assigned portal area.','Finishing prerequisites unlocks only areas already assigned to you and introduces the next walkthrough.'],['Edit and revisit training','Admins can use Add a lesson, Edit this lesson and Edit section names and order. Lessons open inline, and Resources & tools has its own team tab.','Admin edits and archives retain recorded progress. Path membership changes apply when training is assigned again.']]:area==='meetings'?[['Your team meetings','Check the selected date, required or optional label, and Toronto start and end times. Weekend schedules are empty because there are no meetings.','Testing’s daily co-op meeting is optional.'],['Join and check changes','Choose the meeting’s Join button to open Teams, Zoom or its linked service. A cancelled or suspended meeting has no join link in the portal.','Portal cancellations do not cancel the underlying Teams event.'],['Training room access','The training room needs a timed team or individual grant. Its join link is unavailable outside your approved window.','Ask your team admin if you need an access window.']]:area==='spreadsheets'?[['Your team spreadsheets','Choose Open spreadsheet on a resource card. It opens in a new tab so you can keep this portal available.','Google may ask you to sign in with the account shared on that sheet.'],['Working in shared sheets','Follow your team’s instructions and check the correct sheet before changing shared information. Portal access does not grant Google editing permission.','If Google denies access, ask your team admin to check its sharing settings.']]:area==='interviews'?[['Your HR interview workspace','Your interview dashboard shows your activity and recent interviews. My interviews and Follow-up tracker remain specific to your account.','The full interview walkthrough follows this introduction.'],['Your interview responsibilities','Use New interview during the conversation, save your notes and complete the three follow-up tasks. Recruitment progress is recorded separately by HR admins.','Gerrie will explain every form section in the full walkthrough.']]:[['Your team home','Start with a large team tile. Your primary and secondary teams appear here, followed by tools for any administrator roles.','The Guhuza name returns Home. With one team, Home opens that team directly.'],['Areas and training','Inside a team, tiles lead to Training, Projects and other assigned tools. A locked tile explains that required training must be completed first.','Missing tiles mean that area has not been assigned to you.'],['Your account and help','Your profile and settings remain in the account menu at the top right. Use Help & walkthrough to replay guidance.','Team admins manage their own resources; portal admins manage memberships.']];let index=0;const next=button('Next',async()=>{if(index<pages.length-1){index++;draw();return;}try{if(area!=='portal'&&!replay){const r=await api.db.from('area_guides').insert({user_id:api.user().id,team_id:team,area});if(r.error&&r.error.code!=='23505')throw r.error;guides.push({team_id:team,area});}dialog.close();if(area==='interviews'){$('tourStart').click();}}catch(e){tip.textContent='Could not save walkthrough completion: '+e.message;}} ,'primary'),back=button('Back',()=>{index--;draw();});actions.append(back,next);function draw(){const p=pages[index];count.textContent='GERRIE’S GUIDE · '+(index+1)+' OF '+pages.length;heading.textContent=p[0];text.textContent=p[1];tip.textContent=p[2];back.disabled=index===0;next.textContent=index===pages.length-1?(area==='interviews'?'Start full interview walkthrough':'Finish'):'Next';heading.tabIndex=-1;heading.focus();}dialog.showModal();draw();}


